PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "policy_requests" ("id" integer primary key autoincrement not null, "client_request_id" varchar not null, "agent_id" varchar not null, "customer_name" varchar not null, "date_of_birth" date not null, "destination" varchar check ("destination" in ('DOMESTIC', 'INTERNATIONAL')) not null, "trip_start" date not null, "trip_end" date not null, "plan_code" varchar check ("plan_code" in ('BASIC', 'PLUS', 'PREMIUM')) not null, "sum_insured" numeric not null, "travel_days" integer not null, "premium" numeric, "status" varchar not null default 'RECEIVED', "policy_number" varchar, "provider_reference" varchar, "attempt_count" integer not null default '0', "last_error" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "policy_state_histories" ("id" integer primary key autoincrement not null, "policy_request_id" integer not null, "from_state" varchar, "to_state" varchar not null, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("policy_request_id") references "policy_requests"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "issuance_attempts" ("id" integer primary key autoincrement not null, "policy_request_id" integer not null, "attempt_number" integer not null, "scenario" varchar, "request_payload" text, "response_payload" text, "status" varchar not null, "created_at" datetime, "updated_at" datetime, foreign key("policy_request_id") references "policy_requests"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "mock_insurer_policies" ("id" integer primary key autoincrement not null, "client_request_id" varchar not null, "provider_reference" varchar not null, "policy_number" varchar not null, "status" varchar not null default 'ISSUED', "created_at" datetime, "updated_at" datetime);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "uq_agent_client_request" on "policy_requests" ("agent_id", "client_request_id");
CREATE INDEX "policy_requests_status_index" on "policy_requests" ("status");
CREATE UNIQUE INDEX "policy_requests_policy_number_unique" on "policy_requests" ("policy_number");
CREATE INDEX "policy_state_histories_policy_request_id_created_at_index" on "policy_state_histories" ("policy_request_id", "created_at");
CREATE INDEX "issuance_attempts_policy_request_id_attempt_number_index" on "issuance_attempts" ("policy_request_id", "attempt_number");
CREATE UNIQUE INDEX "mock_insurer_policies_client_request_id_unique" on "mock_insurer_policies" ("client_request_id");
CREATE UNIQUE INDEX "mock_insurer_policies_provider_reference_unique" on "mock_insurer_policies" ("provider_reference");
CREATE UNIQUE INDEX "mock_insurer_policies_policy_number_unique" on "mock_insurer_policies" ("policy_number");
COMMIT;
